<?php
namespace App\Domain\Storage\Services;
use App\Domain\Documents\Enums\DocumentStatus;use App\Models\{Document,DocumentFile,DocumentVersion,FileIntegrityCheck};use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use RuntimeException;
class SecurePdfIngestor{public function __construct(private PdfInspector $inspector){}public function ingest(Document $document,UploadedFile $upload,int $userId):DocumentFile{$qDisk=config('dms.quarantine_disk');$dDisk=config('dms.documents_disk');$token=(string)Str::ulid();$qKey=trim(config('dms.quarantine_prefix'),'/').'/'.$token.'.pdf';$stream=fopen($upload->getRealPath(),'rb');Storage::disk($qDisk)->writeStream($qKey,$stream);if(is_resource($stream))fclose($stream);$qPath=Storage::disk($qDisk)->path($qKey);try{$info=$this->inspector->inspect($qPath);if(DocumentFile::where('sha256',$info['sha256'])->where('file_role','MASTER')->exists())throw new RuntimeException('An identical archival master already exists in the repository.');$result=DB::transaction(function()use($document,$upload,$userId,$dDisk,$qDisk,$qKey,$qPath,$info){$last=$document->versions()->lockForUpdate()->max('version_number')??0;$number=$last+1;$version=DocumentVersion::create(['document_id'=>$document->id,'version_number'=>$number,'change_reason'=>$number===1?'INITIAL_SCAN':'AUTHORIZED_REPLACEMENT','supersedes_version_id'=>$document->current_version_id,'created_by'=>$userId]);$stored=Str::lower((string)Str::ulid()).'.pdf';$key=trim(config('dms.documents_prefix'),'/').'/'.$document->ulid.'/versions/'.str_pad((string)$number,6,'0',STR_PAD_LEFT).'/master/'.$stored;$source=fopen($qPath,'rb');Storage::disk($dDisk)->writeStream($key,$source);if(is_resource($source))fclose($source);$file=DocumentFile::create(['document_version_id'=>$version->id,'file_role'=>'MASTER','storage_disk'=>$dDisk,'storage_key'=>$key,'original_filename'=>basename($upload->getClientOriginalName()),'stored_filename'=>$stored,'mime_type'=>$info['mime_type'],'size_bytes'=>$info['size_bytes'],'page_count'=>$info['page_count'],'sha256'=>$info['sha256'],'processing_status'=>'MASTER_ACCEPTED','uploaded_by'=>$userId,'uploaded_at'=>now()]);$absolute=Storage::disk($dDisk)->path($key);$post=hash_file('sha256',$absolute);FileIntegrityCheck::create(['document_file_id'=>$file->id,'expected_sha256'=>$info['sha256'],'calculated_sha256'=>$post,'result'=>hash_equals($info['sha256'],$post)?'PASS':'FAIL','checked_by_type'=>'INGEST','checked_at'=>now()]);if(!hash_equals($info['sha256'],$post))throw new RuntimeException('Integrity verification failed after secure storage promotion.');$document->forceFill(['current_version_id'=>$version->id,'status'=>DocumentStatus::Processing])->save();DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>DocumentStatus::AwaitingUpload->value,'to_status'=>DocumentStatus::Processing->value,'reason'=>'Archival master accepted','changed_by'=>$userId,'changed_at'=>now(),'created_at'=>now()]);return $file;},3);Storage::disk($qDisk)->delete($qKey);return $result;}catch(\Throwable $e){Storage::disk($qDisk)->delete($qKey);throw $e;}}}
